package src;

public class elseif {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int num=-20;
		if(num>0)
		{
			System.out.println("positive number");
		}else {
			System.out.println("negative number");
		}
		System.out.println("hello");//outer statement
		}

	}

